58	/*
59	 * Feature detection of the underlying libzip: zip_encryption_method_supported exists
60	 * since libzip 1.2.0 and zip_compression_method_supported since libzip 1.7.0. They are
61	 * used to check, before anything is modified, that the compression/encryption method
62	 * selected on the archive can actually be applied. With an older libzip, the check
63	 * performed after the addition (with a full rollback of the call) is the only line of
64	 * defense.
65	 */
66	#if defined(LIBZIP_VERSION_MAJOR) && defined(LIBZIP_VERSION_MINOR)
67	  #if LIBZIP_VERSION_MAJOR>1 || (LIBZIP_VERSION_MAJOR==1 && LIBZIP_VERSION_MINOR>=2)
68	    #define LIBZIPPP_HAS_ENCRYPTION_METHOD_SUPPORTED 1
69	  #endif
70	  #if LIBZIP_VERSION_MAJOR>1 || (LIBZIP_VERSION_MAJOR==1 && LIBZIP_VERSION_MINOR>=7)
71	    #define LIBZIPPP_HAS_COMPRESSION_METHOD_SUPPORTED 1
72	  #endif
73	#endif
