75	static libzippp_uint16 convertCompressionToLibzip(CompressionMethod comp) {
76	    switch(comp) {
77	        case CompressionMethod::STORE:
78	            return ZIP_CM_STORE;
79	#ifdef ZIP_CM_BZIP2
80	        case CompressionMethod::BZIP2:
81	            return ZIP_CM_BZIP2;
82	#endif
83	        case CompressionMethod::DEFLATE:
84	            return ZIP_CM_DEFLATE;
85	#ifdef ZIP_CM_XZ
86	        case CompressionMethod::XZ:
87	            return ZIP_CM_XZ;
88	#endif
89	#ifdef ZIP_CM_ZSTD
90	        case CompressionMethod::ZSTD:
91	            return ZIP_CM_ZSTD;
92	#endif
93	        default:
94	            return ZIP_CM_DEFAULT;
95	    }
96	}
97	
98	static CompressionMethod convertCompressionFromLibzip(libzippp_uint16 comp) {
99	    switch(comp) {
100	      case ZIP_CM_STORE:
101	          return CompressionMethod::STORE;
102	#ifdef ZIP_CM_BZIP2
103	      case ZIP_CM_BZIP2:
104	          return CompressionMethod::BZIP2;
105	#endif
106	      case ZIP_CM_DEFLATE:
107	          return CompressionMethod::DEFLATE;
108	#ifdef ZIP_CM_XZ
109	      case ZIP_CM_XZ:
110	          return CompressionMethod::XZ;
111	#endif
112	#ifdef ZIP_CM_ZSTD
113	      case ZIP_CM_ZSTD:
114	          return CompressionMethod::ZSTD;
115	#endif
116	      default:
117	          return CompressionMethod::DEFAULT;
118	    }
119	}
