122	    static void callErrorHandlingCallbackFunc(const std::string& message, int zip_error_code, int system_error_code, ErrorHandlerCallback* callback) {
123	        zip_error_t error;
124	        zip_error_init(&error);
125	        zip_error_set(&error, zip_error_code, system_error_code);
126	        std::string strerror(zip_error_strerror(&error));
127	        (*callback)(message, strerror, zip_error_code, system_error_code);
128	        zip_error_fini(&error);
129	    }
130	
131	    static void callErrorHandlingCallback(zip* zipHandle, const std::string& msg, ErrorHandlerCallback* callback) {
132	        if (zipHandle!=nullptr) {
133	            zip_error_t* error_code = zip_get_error(zipHandle);
134	            callErrorHandlingCallbackFunc(msg, error_code->zip_err, error_code->sys_err, callback);
135	        } else {
136	            callErrorHandlingCallbackFunc("", -1, -1, callback);
137	        }
138	    }
139	
140	    static void callErrorHandlingCallback(zip_error_t* error, const std::string& msg, ErrorHandlerCallback* callback) {
141	        int error_code_zip, error_code_system;
142	        error_code_zip = zip_error_code_zip(error);
143	        error_code_system = zip_error_code_system(error);
144	        callErrorHandlingCallbackFunc(msg, error_code_zip, error_code_system, callback);
145	    }
146	}
