189	string ZipEntry::readAsText(ZipArchive::State state, libzippp_uint64 size) const {
190	    if (isNull()) { return string(); }
191	    if (session.expired()) { return string(); } //the opening this entry comes from has ended
192	    char* content = (char*)zipFile->readEntry(*this, true, state, size);
193	    if (content==nullptr) { return string(); } //happen if the ZipArchive has been closed or the entry does not exist in the state
194	
195	    //the read length is computed from the entry AS IT IS IN THE REQUESTED STATE instead of
196	    //from the size captured when this object was obtained: a replacement may be longer,
197	    //shorter or empty and the object is not required to be fetched again to read it
198	    libzippp_uint64 maxSize = zipFile->getEntry((libzippp_int64)index, state).getSize();
199	    libzippp_uint64 length = size==0 || size>maxSize ? maxSize : size;
200	    string str(content, length); //the extra '\0' appended by readEntry is not part of the content
201	    delete[] content;
202	    return str;
203	}
