211	basic_string<libzippp_uint8> ZipEntry::readAsBinaryString(ZipArchive::State state, libzippp_uint64 size) const {
212	    if (isNull()) { return basic_string<libzippp_uint8>(); }
213	    if (session.expired()) { return basic_string<libzippp_uint8>(); }
214	    libzippp_uint8* content = (libzippp_uint8*)zipFile->readEntry(*this, true, state, size);
215	    if (content==nullptr) { return basic_string<libzippp_uint8>(); } //happen if the ZipArchive has been closed or the entry does not exist in the state
216	
217	    //see readAsText: the length must reflect the requested state (zero bytes inside the
218	    //content are preserved, the extra '\0' is only an allocation artifact)
219	    libzippp_uint64 maxSize = zipFile->getEntry((libzippp_int64)index, state).getSize();
220	    libzippp_uint64 length = size==0 || size>maxSize ? maxSize : size;
221	    basic_string<libzippp_uint8> str(content, length);
222	    delete[] content;
223	    return str;
224	}
