226	int ZipEntry::readContent(std::ostream& ofOutput, ZipArchive::State state, libzippp_uint64 chunksize) const {
227	   //an invalid stream is reported first, as for a valid entry; the error codes below
228	   //are the ones guaranteed when the stream itself is valid
229	   if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
230	   //a null entry is invalid; a non-null entry whose opening ended is reported as coming
231	   //from a no-longer-open archive. The archive object itself may have been destroyed,
232	   //hence these checks must not dereference zipFile.
233	   if (isNull()) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
234	   if (session.expired()) { return LIBZIPPP_ERROR_NOT_OPEN; }
235	   return zipFile->readEntry(*this, ofOutput, state, chunksize);
236	}
