271	bool ZipArchive::isEntryUsable(const ZipEntry& entry) const {
272	    if (entry.isNull()) { return false; }
273	    if (entry.zipFile!=this) { return false; }
274	    //the entry must belong to the CURRENT opening of this archive: its session marker
275	    //is the one this archive holds right now
276	    std::shared_ptr<ZipEntrySession> entryOpening = entry.session.lock();
277	    return entryOpening && entryOpening==entrySession;
278	}
