280	ZipArchive::~ZipArchive(void) {
281	    close(); /* discard ??? */
282	
283	    //if the commit failed in close(), the archive is gone anyway: the adopted buffers
284	    //must not outlive it (on a successful close/discard this is a no-op)
285	    releaseAdoptedBuffers();
286	
287	    //whatever close() did (including a failed commit), the archive object itself is
288	    //gone: every entry obtained from any opening must be expired now
289	    endEntrySession();
290	
291	    // ensures all the values are clared
292	    zipHandle = nullptr;
293	    zipSource = nullptr;
294	    bufferData = nullptr;
295	    errorHandlingCallback = nullptr;
296	    listeners.clear();
