337	bool ZipArchive::openBuffer(void** data, libzippp_uint32 size, OpenMode om, bool checkConsistency) {
338	    zip_error_t error;
339	    zip_error_init(&error);
340	
341	    /* create source from buffer */
342	    zip_source* localZipSource = zip_source_buffer_create(*data, size, 0, &error);
343	    if (localZipSource == nullptr) {
344	        Helper::callErrorHandlingCallback(&error, "can't create zip source: %s\n", errorHandlingCallback);
345	        zip_error_fini(&error);
346	        return false;
347	    }
348	
349	    bool open = openSource(localZipSource, om, checkConsistency);
350	    if (open) {
351	        if (om==Write || om==New) {
352	            bufferData = data;
353	            bufferLength = size;
354	
355	            //prevents libzip to delete the source when closing the ZipArchive
356	            zip_source_keep(localZipSource);
357	        }
358	    } else {
359	        zip_source_free(localZipSource);
360	        localZipSource = nullptr;
361	    }
362	    return open;
363	}
