365	bool ZipArchive::openSource(zip_source* source, OpenMode om, bool checkConsistency) {
366	    int zipFlag = 0;
367	    if (om == ReadOnly) { zipFlag = 0; }
368	    else if (om == Write) { zipFlag = ZIP_CREATE; }
369	    else if (om == New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
370	    else { return false; }
371	    if (checkConsistency) {
372	        zipFlag = zipFlag | ZIP_CHECKCONS;
373	    }
374	
375	    zip_error_t error;
376	    zip_error_init(&error);
377	
378	    /* open zip archive from source */
379	    zipHandle = zip_open_from_source(source, zipFlag, &error);
380	    if (zipHandle == nullptr) {
381	        Helper::callErrorHandlingCallback(&error, "can't open zip from source: %s\n", errorHandlingCallback);
382	        zip_error_fini(&error);
383	        return false;
384	    }
385	    zip_error_fini(&error);
386	
387	    zipSource = source;
388	
389	#ifdef LIBZIPPP_WITH_ENCRYPTION
390	    if (isEncrypted()) {
391	        int result = zip_set_default_password(zipHandle, password.c_str());
392	        if (result != 0) {
393	            close();
394	            return false;
395	        }
396	    }
397	#endif
398	
399	    mode = om;
400	    beginEntrySession(); //entries created by this opening share this marker
401	    return true;
402	}
