404	bool ZipArchive::open(OpenMode om, bool checkConsistency) {
405	    if (isOpen()) { return om==mode; }
406	
407	    int zipFlag = 0;
408	    if (om==ReadOnly) { zipFlag = 0; }
409	    else if (om==Write) { zipFlag = ZIP_CREATE; }
410	    else if (om==New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
411	    else { return false; }
412	
413	    if (checkConsistency) {
414	        zipFlag = zipFlag | ZIP_CHECKCONS;
415	    }
416	
417	    int errorFlag = 0;
418	    zipHandle = zip_open(path.c_str(), zipFlag, &errorFlag);
419	
420	    //error during opening of the file
421	    if (errorFlag!=ZIP_ER_OK) {
422	        zip_error_t error;
423	        zip_error_init_with_code(&error, errorFlag);
424	        Helper::callErrorHandlingCallback(&error, "unable to open archive: %s\n", errorHandlingCallback);
425	        zip_error_fini(&error);
426	
427	        zipHandle = nullptr;
428	        return false;
429	    }
430	
431	    if (zipHandle!=nullptr) {
432	#ifdef LIBZIPPP_WITH_ENCRYPTION
433	        if (isEncrypted()) {
434	            int result = zip_set_default_password(zipHandle, password.c_str());
435	            if (result!=0) {
436	                close();
437	                return false;
438	            }
439	        }
440	#endif
441	
442	        mode = om;
443	        beginEntrySession(); //entries created by this opening share this marker
444	        return true;
445	    }
446	
447	    return false;
448	}
