450	void progress_callback(zip* /*archive*/, double progression, void* ud) {
451	    ZipArchive* za = static_cast<ZipArchive*>(ud);
452	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
453	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
454	        ZipProgressListener* listener = *it;
455	        listener->progression(progression);
456	    }
457	}
458	
459	int progress_cancel_callback(zip* /*archive*/, void* ud) {
460	    ZipArchive* za = static_cast<ZipArchive*>(ud);
461	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
462	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
463	        ZipProgressListener* listener = *it;
464	        if (listener->cancel())
465	          return 1;
466	    }
467	    return 0;
468	}
