470	int ZipArchive::close(void) {
471	    if (isOpen()) {
472	
473	        //do not handle zipSource at all because it will be deleted by libzip
474	        //directly when not necessary anymore
475	
476	        if (!listeners.empty()) {
477	            zip_register_progress_callback_with_state(zipHandle, progressPrecision, progress_callback, nullptr, this);
478	            zip_register_cancel_callback_with_state(zipHandle, progress_cancel_callback, nullptr, this);
479	        }
480	
481	        //avoid to reset the progress when unzipping
482	        if (mode != ReadOnly) {
483	            progress_callback(zipHandle, 0, this); //enforce the first progression call to be zero
484	        }
485	
486	        int result = zip_close(zipHandle);
487	        if (result!=0) {
488	            //typically a cancelled commit: the archive is still open and usable, the
489	            //session is left untouched so existing entries and their copies remain valid
490	            Helper::callErrorHandlingCallback(zipHandle, "unable to close archive: %s\n", errorHandlingCallback);
491	            return LIBZIPPP_ERROR_HANDLE_FAILURE;
492	        }
493	
494	        zipHandle = nullptr;
495	        //the opening really ended (even if the buffer readback below fails afterwards):
496	        //all entries obtained during it must expire now
497	        endEntrySession();
498	        //the commit consumed the sources: the buffers adopted with freeData=true are
499	        //no longer referenced by libzip and are released exactly once, here
500	        releaseAdoptedBuffers();
501	        progress_callback(zipHandle, 1, this); //enforce the last progression call to be one
502	
503	        //push back the changes in the buffer
504	        int res_code = LIBZIPPP_OK;
505	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
506	            int srcOpen = zip_source_open(zipSource);
507	            if (srcOpen==0) {
508	                //IMPORTANT: the rewritten archive is read back into a *freshly allocated*
509	                //buffer. We must never read into nor realloc *bufferData here: that memory
510	                //is the storage backing the libzip source we are currently reading from.
511	                //Reusing it aliases the source and, depending on the libzip version (i.e.
512	                //whether it takes ownership of the buffer when writing), it makes
513	                //zip_source_free() release a buffer that realloc() already moved/freed,
514	                //which results in a double-free (see double_free_report / fromWritableBuffer).
515	                zip_int64_t increment = 1024;
516	                zip_int64_t capacity = bufferLength>0 ? static_cast<zip_int64_t>(bufferLength) : increment;
517	                char* outBuffer = static_cast<char*>(malloc(capacity * sizeof(char)));
518	                char* tempBuffer = outBuffer;
519	                zip_int64_t tempBufferSize = capacity;
520	                zip_int64_t totalRead = 0;
521	                zip_int64_t read = (outBuffer==nullptr) ? -1 : zip_source_read(zipSource, tempBuffer, tempBufferSize);
522	                while(read>0) {
523	                    totalRead += read;
524	                    if (totalRead>=capacity) {
525	                        zip_int64_t newCapacity = capacity + increment;
526	                        char* grownBuffer = static_cast<char*>(realloc(outBuffer, newCapacity * sizeof(char)));
527	                        if (grownBuffer==nullptr) {
528	                            Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: unable to extend buffer\n", errorHandlingCallback);
529	                            ::free(outBuffer);
530	                            outBuffer = nullptr;
531	                            read = -1;
532	                            break;
533	                        }
534	                        outBuffer = grownBuffer;
535	                        capacity = newCapacity;
536	                    }
537	                    tempBuffer = outBuffer+totalRead;
538	                    tempBufferSize = capacity-totalRead;
539	                    read = zip_source_read(zipSource, tempBuffer, tempBufferSize);
540	                }
541	
542	                zip_source_close(zipSource);
543	
544	                if (outBuffer!=nullptr && read>=0) {
545	                    //freeing zipSource first guarantees libzip has released whatever it owns
546	                    //before we touch *bufferData. With freep=0 (see openBuffer) libzip never
547	                    //frees *bufferData itself, so reclaiming it here is safe and leak-free.
548	                    zip_source_free(zipSource);
549	                    zipSource = nullptr;
550	
551	                    ::free(*bufferData);
552	                    *bufferData = outBuffer;
553	                    bufferLength = totalRead;
554	                } else {
555	                    Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
556	                    res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
557	                    if (outBuffer!=nullptr) { ::free(outBuffer); }
558	                    zip_source_free(zipSource);
559	                    zipSource = nullptr;
560	                }
561	            } else {
562	                Helper::callErrorHandlingCallback((zip*)nullptr, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
563	                res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
564	
565	                zip_source_free(zipSource);
566	                zipSource = nullptr;
567	            }
568	        }
569	
570	        mode = NotOpen;
571	        return res_code;
572	    }
573	
574	    return LIBZIPPP_OK;
575	}
