577	void ZipArchive::discard(void) {
578	    if (isOpen()) {
579	        zip_discard(zipHandle);
580	        zipHandle = nullptr;
581	
582	        //the pending sources are gone: release the buffers adopted with freeData=true
583	        releaseAdoptedBuffers();
584	
585	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
586	            zip_source_free(zipSource);
587	            zipSource = nullptr;
588	        }
589	
590	        mode = NotOpen;
591	        endEntrySession(); //discarded opening: all its entries expire
592	    }
593	}
