667	ZipEntry ZipArchive::resolveEntry(const ZipEntry& zipEntry, State state, libzippp_uint64* outSize) const {
668	    if (outSize!=nullptr) { *outSize = 0; }
669	
670	    //a null-ZipEntry (e.g. obtained through getEntry in a state where the name does not
671	    //exist) cannot be resolved in any state, nor can an entry coming from another archive
672	    //or from an opening that has ended
673	    if (!isEntryUsable(zipEntry)) { return ZipEntry(); }
674	
675	    int flag = stateFlags(state);
676	    struct zip_stat stat;
677	    zip_stat_init(&stat);
678	
679	    //stat the (stable) slot in the requested state: this fails for an entry deleted in the
680	    //current state (read with Current) or a newly added entry (read with Original)
681	    if (zip_stat_index(zipHandle, zipEntry.getIndex(), flag, &stat)!=0) { return ZipEntry(); }
682	
683	    ZipEntry resolved = createEntry(&stat);
684	    if (outSize!=nullptr) { *outSize = stat.size; }
685	    return resolved;
686	}
