688	vector<ZipEntry> ZipArchive::getEntries(State state) const {
689	    if (!isOpen()) { return vector<ZipEntry>(); }
690	
691	    struct zip_stat stat;
692	    zip_stat_init(&stat);
693	
694	    vector<ZipEntry> entries;
695	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
696	    libzippp_int64 nbEntries = getNbEntries(state);
697	    for(libzippp_int64 i=0 ; i<nbEntries ; ++i) {
698	        int result = zip_stat_index(zipHandle, i, flag, &stat);
699	        if (result==0) {
700	            ZipEntry entry = createEntry(&stat);
701	            entries.push_back(entry);
702	        } else {
703	            //TODO handle read error => crash ?
704	        }
705	    }
706	    return entries;
707	}
