722	ZipEntry ZipArchive::getEntry(const string& name, bool excludeDirectories, bool caseSensitive, State state) const {
723	    if (isOpen()) {
724	        int flags = 0;
725	        if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
726	        if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
727	        if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
728	        else { flags = flags | ZIP_FL_ENC_GUESS; }
729	
730	        libzippp_int64 index = zip_name_locate(zipHandle, name.c_str(), flags);
731	        if (index>=0) {
732	            //the located index must be stat'd in the SAME state: locating a renamed entry
733	            //in the original state gives the original slot, whose name and size are the
734	            //original ones (using the current stat here would return the new name/length)
735	            return getEntry(index, state);
736	        } else {
737	            //name not found in the requested state
738	        }
739	    }
740	    return ZipEntry();
741	}
