748	        int result = zip_stat_index(zipHandle, index, flag, &stat);
749	        if (result==0) {
750	            return createEntry(&stat);
751	        } else {
752	            //index not found / invalid index
753	        }
754	    }
755	    return ZipEntry();
756	}
