780	void* ZipArchive::readEntry(const ZipEntry& zipEntry, bool asText, State state, libzippp_uint64 size) const {
781	    if (!isOpen()) { return nullptr; }
782	    if (!isEntryUsable(zipEntry)) { return nullptr; }
783	
784	    //resolve the entry in the requested state: the uncompressed size and the existence of
785	    //the entry depend on the state (a replacement may be longer, shorter or empty, a deleted
786	    //entry is only readable as Original and a newly added one only as Current)
787	    libzippp_uint64 entrySize = 0;
788	    ZipEntry resolved = resolveEntry(zipEntry, state, &entrySize);
789	    if (resolved.isNull()) { return nullptr; }
790	
791	    int flag = stateFlags(state);
792	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
793	    if (zipFile) {
794	        //zero means "read the whole content" and a too big length returns all of it; the
795	        //captured zipEntry size is intentionally never used to bound the read
796	        libzippp_uint64 uisize = size==0 || size>entrySize ? entrySize : size;
797	
798	        char* data = NEW_CHAR_ARRAY(uisize+(asText ? 1 : 0))
799	        if (!data) { //allocation error
800	            zip_fclose(zipFile);
801	            return nullptr;
802	        }
803	
804	        libzippp_int64 result = zip_fread(zipFile, data, uisize);
805	        zip_fclose(zipFile);
806	
807	        //avoid buffer copy
808	        if (asText) { data[uisize] = '\0'; }
809	
810	        libzippp_int64 isize = (libzippp_int64)uisize;
811	        if (result==isize) {
812	            return data;
813	        } else { //unexpected number of bytes read => crash ?
814	            delete[] data;
815	        }
816	    } else {
817	        //unable to read the entry (e.g. it does not exist in the requested state) => crash ?
818	    }
819	
820	    return nullptr;
821	}
822	
823	void* ZipArchive::readEntry(const string& zipEntry, bool asText, State state, libzippp_uint64 size) const {
824	    //the name is interpreted in the requested state: there is no fallback to the other state
825	    //if the name does not exist in this one
826	    ZipEntry entry = getEntry(zipEntry, false, true, state);
827	    if (entry.isNull()) { return nullptr; }
828	    return readEntry(entry, asText, state, size);
829	}
830	
831	int ZipArchive::deleteEntry(const ZipEntry& entry) const {
832	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
833	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
834	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //deletion not allowed
835	
836	    if (entry.isFile()) {
837	        int result = zip_delete(zipHandle, entry.getIndex());
838	        if (result==0) { return 1; }
839	        return LIBZIPPP_ERROR_UNKNOWN; //unable to delete the entry
840	    } else {
841	        int counter = 0;
842	        vector<ZipEntry> allEntries = getEntries();
843	        vector<ZipEntry>::const_iterator eit;
844	        for(eit=allEntries.begin() ; eit!=allEntries.end() ; ++eit) {
845	            ZipEntry ze = *eit;
846	            string::size_type startPosition = ze.getName().find(entry.getName());
847	            if (startPosition==0) {
848	                int result = zip_delete(zipHandle, ze.getIndex());
849	                if (result==0) { ++counter; }
850	                else { return LIBZIPPP_ERROR_UNKNOWN; } //unable to remove the current entry
851	            }
852	        }
853	        return counter;
854	    }
855	}
