857	int ZipArchive::deleteEntry(const string& e) const {
858	    ZipEntry entry = getEntry(e);
859	    if (entry.isNull()) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
860	    return deleteEntry(entry);
861	}
862	
863	int ZipArchive::renameEntry(const ZipEntry& entry, const string& newNameIn) const {
864	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
865	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
866	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //renaming not allowed
867	    if (newNameIn.length()==0) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
868	
869	    bool isDir = entry.isDirectory();
870	    string newName = newNameIn;
871	    if (isDir) {
872	        //a '/' is automatically appended to the destination of a directory
873	        if (!LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { newName += LIBZIPPP_ENTRY_PATH_SEPARATOR; }
874	    } else {
875	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { return LIBZIPPP_ERROR_INVALID_PARAMETER; } //a file cannot be renamed as a directory
876	    }
877	
878	    string sourceName = entry.getName();
879	    if (newName==sourceName) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
880	
881	    /*
882	     * Enumerate ALL the entries of the CURRENT state of the archive (i.e. including any
883	     * uncommitted addition/deletion/replacement/rename). Slots freed by zip_delete are
884	     * reported with a null name by libzip and simply skipped.
885	     */
886	    struct RenameItem {
887	        zip_uint64_t index;
888	        string oldName;
889	        string targetName;
890	    };
891	    vector<RenameItem> movedItems;
892	    vector<string> externalNames;
893	
894	    zip_int64_t nbSlots = zip_get_num_entries(zipHandle, 0);
895	    for(zip_int64_t i=0 ; i<nbSlots ; ++i) {
896	        const char* currentName = zip_get_name(zipHandle, (zip_uint64_t)i, ZIP_FL_ENC_GUESS);
897	        if (currentName==nullptr) { continue; } //entry deleted in the current (uncommitted) state
898	
899	        string name(currentName);
900	        bool participates = false;
901	        string targetName;
902	        if (isDir) {
903	            if (name==sourceName) {
904	                participates = true;
905	                targetName = newName;
906	            } else if (name.compare(0, sourceName.length(), sourceName)==0) {
907	                participates = true; //descendant of the moved directory
908	                targetName = newName + name.substr(sourceName.length());
909	            }
910	        } else {
911	            participates = (name==sourceName);
912	            targetName = newName;
913	        }
914	
915	        if (participates) {
916	            movedItems.push_back(RenameItem{(zip_uint64_t)i, name, targetName});
917	        } else {
918	            externalNames.push_back(name);
919	        }
920	    }
921	
922	    //the source entry itself must be part of the current archive
923	    bool sourceFound = false;
924	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
925	        if (it->oldName==sourceName) { sourceFound = true; break; }
926	    }
927	    if (!sourceFound) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
928	
929	    /*
930	     * Detect conflicts against the CURRENT state only: any entry that does not participate
931	     * in the move must not occupy the destination itself nor lie below it. Entries whose
932	     * parent directories are only implicit (no explicit directory entry in the archive) are
933	     * listed here as well, so a file such as new/target/last.txt prevents src/ from being
934	     * moved to new/target/ even when no new/ or new/target/ directory entry exists.
935	     */
936	    for(vector<string>::const_iterator it=externalNames.begin() ; it!=externalNames.end() ; ++it) {
937	        const string& external = *it;
938	        if (isDir) {
939	            if (external==newName || external.compare(0, newName.length(), newName)==0) {
940	                return LIBZIPPP_ERROR_UNKNOWN; //destination already occupied by an external entry: no overwrite, no merge
941	            }
942	        } else {
943	            if (external==newName) {
944	                return LIBZIPPP_ERROR_UNKNOWN; //the destination file already exists
945	            }
946	        }
947	    }
948	
949	    /*
950	     * Compute the (explicit) parent directories that will be missing once the entries have
951	     * been moved. A directory that is itself moved never has to be re-created here (it keeps
952	     * existing as an entry, only its name changes), even when a moved entry's new parent
953	     * chain goes through it.
954	     */
955	    vector<string> parentsToCreate;
956	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
957	        //for a directory target (ending with '/'), the first parent to consider is above the
958	        //target directory itself, hence the search starts at the penultimate separator
959	        string::size_type searchPos = it->targetName.length()-1;
960	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(it->targetName) && searchPos>0) { searchPos -= 1; }
961	        string::size_type slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, searchPos);
962	        while(slash!=string::npos && slash>0) {
963	            string parent = it->targetName.substr(0, slash+1);
964	
965	            //a moved destination already exists as an entry after the move
966	            bool isMovedDestination = false;
967	            for(vector<RenameItem>::const_iterator mit=movedItems.begin() ; mit!=movedItems.end() ; ++mit) {
968	                if (mit->targetName==parent) { isMovedDestination = true; break; }
969	            }
970	            if (isMovedDestination) { break; } //all the ancestors above are shared with this moved directory
971	
972	            //an external entry already provides the directory (explicitly)
973	            bool isExternal = false;
974	            for(vector<string>::const_iterator eit=externalNames.begin() ; eit!=externalNames.end() ; ++eit) {
975	                if (*eit==parent) { isExternal = true; break; }
976	            }
977	            if (isExternal) { break; } //the prefix chain up to this directory already exists
978	
979	            bool alreadyScheduled = false;
980	            for(vector<string>::const_iterator pit=parentsToCreate.begin() ; pit!=parentsToCreate.end() ; ++pit) {
981	                if (*pit==parent) { alreadyScheduled = true; break; }
982	            }
983	            if (!alreadyScheduled) { parentsToCreate.push_back(parent); }
984	            slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, slash-1);
985	        }
986	    }
987	    //create the parents from the shallowest to the deepest
988	    std::sort(parentsToCreate.begin(), parentsToCreate.end());
989	
990	    /*
991	     * Apply the rename deepest-first. This ordering is what makes moving a directory below
992	     * its own path possible (e.g. a/ to a/b/): the descendants free the names the ancestors
993	     * are renamed to, and the freshly re-created parent directories are not touched.
994	     */
995	    std::sort(movedItems.begin(), movedItems.end(),
996	              [](const RenameItem& a, const RenameItem& b) { return a.targetName > b.targetName; });
997	
998	    vector<zip_uint64_t> renamedIndices;
999	    vector<string> renamedOldNames;
1000	    bool failure = false;
1001	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1002	        int result = zip_file_rename(zipHandle, it->index, it->targetName.c_str(), ZIP_FL_ENC_GUESS);
1003	        if (result!=0) { failure = true; break; }
1004	        renamedIndices.push_back(it->index);
1005	        renamedOldNames.push_back(it->oldName);
1006	    }
1007	
1008	    //create the missing parent directories (e.g. re-create a/ when a/ moved to a/b/)
1009	    vector<zip_uint64_t> createdDirIndices;
1010	    if (!failure) {
1011	        for(vector<string>::const_iterator it=parentsToCreate.begin() ; it!=parentsToCreate.end() ; ++it) {
1012	            zip_int64_t dirIndex = zip_dir_add(zipHandle, it->c_str(), ZIP_FL_ENC_GUESS);
1013	            if (dirIndex<0) { failure = true; break; }
1014	            createdDirIndices.push_back((zip_uint64_t)dirIndex);
1015	        }
1016	    }
1017	
1018	    if (failure) {
1019	        /*
1020	         * The move could not be completed: undo everything done during THIS call so that the
1021	         * archive is restored to its exact pre-call state. The directories created during
1022	         * the move are removed first (they may occupy the original names), then the renames
1023	         * are replayed in the reverse order (shallowest-first). Any other pending change is
1024	         * left untouched.
1025	         */
1026	        for(vector<zip_uint64_t>::reverse_iterator dit=createdDirIndices.rbegin() ; dit!=createdDirIndices.rend() ; ++dit) {
1027	            zip_delete(zipHandle, *dit);
1028	        }
1029	        for(zip_int64_t k=(zip_int64_t)renamedIndices.size()-1 ; k>=0 ; --k) {
1030	            zip_file_rename(zipHandle, renamedIndices[(size_t)k], renamedOldNames[(size_t)k].c_str(), ZIP_FL_ENC_GUESS);
1031	        }
1032	        return LIBZIPPP_ERROR_UNKNOWN;
1033	    }
1034	
1035	    return (int)movedItems.size();
1036	}
