1074	
1075	bool ZipArchive::createParentDirectories(const string& entryName, vector<libzippp_uint64>& createdDirIndices) const {
1076	    string::size_type lastSlash = entryName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1077	    if (lastSlash==string::npos) { return true; } //no parent directory needed
1078	
1079	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1080	    while (nextSlash!=string::npos && nextSlash<=lastSlash) {
1081	        string pathToCreate = entryName.substr(0, nextSlash+1);
1082	        if (!hasEntry(pathToCreate)) {
1083	            libzippp_int64 dirIndex = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1084	            if (dirIndex<0) {
1085	                //a failed addition must not leave empty parent directories behind
1086	                rollbackCreatedDirectories(createdDirIndices);
1087	                return false;
1088	            }
1089	            createdDirIndices.push_back((libzippp_uint64)dirIndex);
1090	        }
1091	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1092	    }
1093	    return true;
1094	}
1095	
1096	void ZipArchive::rollbackCreatedDirectories(const vector<libzippp_uint64>& createdDirIndices) const {
1097	    //deepest directory first; only the directories created by the failed call are
1098	    //removed, pre-existing ones are never touched
1099	    for(vector<libzippp_uint64>::const_reverse_iterator it=createdDirIndices.rbegin() ; it!=createdDirIndices.rend() ; ++it) {
1100	        zip_delete(zipHandle, *it);
1101	    }
1102	}
1103	
1104	bool ZipArchive::installPreparedSource(const string& entryName, zip_source* source, const vector<libzippp_uint64>& createdDirIndices) const {
1105	    libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
1106	    if (result<0) {
1107	        //the source was not adopted by libzip: release it without touching its data
1108	        zip_source_free(source);
1109	        rollbackCreatedDirectories(createdDirIndices);
1110	        return false;
1111	    }
1112	
1113	    zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
1114	
1115	    bool settingsApplied = true;
1116	    if (useArchiveCompressionMethod) {
1117	        settingsApplied = zip_set_file_compression(zipHandle, result, compressionMethod, 0)==0;
1118	    }
1119	#ifdef LIBZIPPP_WITH_ENCRYPTION
1120	    if (settingsApplied && isEncrypted()) {
1121	        settingsApplied = zip_file_set_encryption(zipHandle, result, encryptionMethod, nullptr)==0;
1122	    }
1123	#endif
1124	
1125	    if (!settingsApplied) {
1126	        /*
1127	         * Last-resort rollback: the applicability of the selected compression and
1128	         * encryption methods was checked before anything was changed, so this is only
1129	         * reachable on an unexpected libzip failure. The entry is reverted and the
1130	         * directories created by this call are removed; every other pending change
1131	         * (other entries, deletions, renames, comments) is left untouched. Reverting
1132	         * the entry also frees the source (which never owns the caller's data here).
1133	         */
1134	        zip_unchange(zipHandle, (zip_uint64_t)result);
1135	        rollbackCreatedDirectories(createdDirIndices);
1136	        return false;
1137	    }
1138	    return true;
1139	}
1140	
1141	bool ZipArchive::addFile(const string& entryName, const string& file) const {
1142	    if (!isOpen()) { return false; }
1143	    if (mode==ReadOnly) { return false; } //adding not allowed
1144	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1145	
1146	    //the source file must be readable: a missing file must not leave any trace
1147	    //(neither a new entry nor parent directories) in the archive
1148	    FILE* probe = fopen(file.c_str(), "rb");
1149	    if (probe==nullptr) { return false; }
1150	    fclose(probe);
1151	
1152	    //the compression and encryption methods selected on the archive must be applicable
1153	    //by this libzip: this is checked before anything is changed so that a failure
1154	    //neither leaves a new entry behind nor silently falls back to weaker settings
1155	    if (!isArchiveCompressionApplicable()) { return false; }
1156	    if (!isArchiveEncryptionApplicable()) { return false; }
1157	
1158	    vector<libzippp_uint64> createdDirIndices;
1159	    if (!createParentDirectories(entryName, createdDirIndices)) { return false; }
1160	
1161	    zip_source* source = zip_source_file(zipHandle, file.c_str(), 0, -1);
1162	    if (source==nullptr) {
1163	        //unable to create the zip_source
1164	        rollbackCreatedDirectories(createdDirIndices);
1165	        return false;
1166	    }
1167	    return installPreparedSource(entryName, source, createdDirIndices);
1168	}
1169	
1170	bool ZipArchive::addData(const string& entryName, const void* data, libzippp_uint64 length, bool freeData) const {
1171	    if (!isOpen()) { return false; }
1172	    if (mode==ReadOnly) { return false; } //adding not allowed
1173	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1174	
1175	    //a null buffer is only valid for an empty content; anything else is rejected
1176	    //before the archive is touched (the caller keeps the ownership of the data)
1177	    if (data==nullptr && length>0) { return false; }
1178	
1179	    //see addFile: the selected compression/encryption must be applicable beforehand
1180	    if (!isArchiveCompressionApplicable()) { return false; }
1181	    if (!isArchiveEncryptionApplicable()) { return false; }
1182	
1183	    vector<libzippp_uint64> createdDirIndices;
1184	    if (!createParentDirectories(entryName, createdDirIndices)) { return false; }
1185	
1186	    /*
1187	     * The buffer is always handed to libzip with freep=0, even when freeData is true:
1188	     * the ownership is transferred to the archive (see adoptedBuffers) only once the
1189	     * data has been fully accepted. Hence a failed call never frees the caller's
1190	     * memory and a successful one guarantees the buffer is released exactly once,
1191	     * when the pending changes are committed or discarded.
1192	     */
1193	    zip_source* source = zip_source_buffer(zipHandle, data, length, 0);
1194	    if (source==nullptr) {
1195	        //unable to create the zip_source
1196	        rollbackCreatedDirectories(createdDirIndices);
1197	        return false;
1198	    }
1199	    if (!installPreparedSource(entryName, source, createdDirIndices)) { return false; }
1200	
1201	    if (freeData && data!=nullptr) {
1202	        adoptedBuffers.push_back(const_cast<void*>(data));
1203	    }
1204	    return true;
1205	}
1206	
1207	bool ZipArchive::addData(const std::string& entryName, const std::basic_string<libzippp_uint8> data) const {
1208	    /*
1209	     * The argument is a copy that is destroyed when this method returns: its content
1210	     * must be copied again into a buffer owned by the archive (through the freeData
1211	     * contract) so that the staged source never references the dead argument when the
1212	     * changes are committed or read back.
1213	     */
1214	    if (data.empty()) { return addData(entryName, nullptr, 0, false); }
1215	    void* copy = malloc(data.size());
1216	    if (copy==nullptr) { return false; }
1217	    memcpy(copy, data.data(), data.size());
1218	    if (!addData(entryName, copy, data.size(), true)) {
1219	        //the ownership was not transferred: the copy is still ours to release
1220	        ::free(copy);
1221	        return false;
1222	    }
1223	    return true;
1224	}
1225	
1226	bool ZipArchive::addEntry(const string& entryName) const {
1227	    if (!isOpen()) { return false; }
1228	    if (mode==ReadOnly) { return false; } //adding not allowed
1229	    if (!LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1230	
1231	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1232	    while (nextSlash!=string::npos) {
1233	        string pathToCreate = entryName.substr(0, nextSlash+1);
1234	        if (!hasEntry(pathToCreate)) {
1235	            libzippp_int64 result = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1236	            if (result==-1) { return false; }
1237	        }
1238	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1239	    }
1240	
1241	    return true;
1242	}
1243	
1244	void ZipArchive::removeProgressListener(ZipProgressListener* listener) {
1245	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
1246	        ZipProgressListener* l = *it;
1247	        if (l==listener) {
1248	            listeners.erase(it);
1249	            break;
1250	        }
1251	    }
1252	}
1253	
1254	void ZipArchive::setCompressionMethod(CompressionMethod comp)
1255	{
1256	    useArchiveCompressionMethod = comp!=CompressionMethod::DEFAULT;
1257	    compressionMethod = convertCompressionToLibzip(comp);
1258	}
1259	
1260	CompressionMethod ZipArchive::getCompressionMethod(void) const {
1261	    return convertCompressionFromLibzip(compressionMethod);
1262	}
1263	
1264	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::ostream& ofOutput, State state, libzippp_uint64 chunksize) const {
1265	    if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1266	    std::function<bool(const void*,libzippp_uint64)> writeFunc = [&ofOutput](const void* data,libzippp_uint64 size){ ofOutput.write((char*)data, size); return bool(ofOutput); };
1267	    return readEntry(zipEntry, writeFunc, state, chunksize);
1268	}
1269	
1270	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::function<bool(const void*,libzippp_uint64)> writeFunc, State state, libzippp_uint64 chunksize) const {
1271	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1272	    //null entries, entries from other archives and entries from a previous opening are
1273	    //rejected before any data delivery (the output stream/callback is left untouched)
1274	    if (!isEntryUsable(zipEntry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1275	
1276	    //resolve the entry in the requested state: its existence and uncompressed size depend
1277	    //on the state. When it does not exist in the state, no data is delivered at all.
1278	    libzippp_uint64 maxSize = 0;
1279	    ZipEntry resolved = resolveEntry(zipEntry, state, &maxSize);
1280	    if (resolved.isNull()) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1281	
1282	    if (!chunksize) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; } // use the default chunk size (512K) if not specified by the user
1283	
1284	    int flag = stateFlags(state);
1285	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
1286	    if (!zipFile) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1287	
1288	    int iRes = LIBZIPPP_OK;
1289	
1290	    //an empty content succeeds without reading anything; a single zero-length delivery is
1291	    //still signalled to the output (this matches the historical behavior)
1292	    if (maxSize==0) {
1293	        if (!writeFunc("", 0)) {
1294	            zip_fclose(zipFile);
1295	            return LIBZIPPP_ERROR_OWRITE_FAILURE;
1296	        }
1297	        zip_fclose(zipFile);
1298	        return LIBZIPPP_OK;
1299	    }
1300	
1301	    //only allocate what a single delivery may need (the whole content when it is smaller
1302	    //than the chunk size) instead of the chunk size in every case
1303	    libzippp_uint64 bufferSize = maxSize<chunksize ? maxSize : chunksize;
1304	    char* data = NEW_CHAR_ARRAY(bufferSize)
1305	    if (data!=nullptr) {
1306	        //stream the exact, state-resolved length in successive chunks: this delivers the
1307	        //whole content exactly once (chunksize bigger than, equal to, or not a divisor of
1308	        //the content length are all handled by the same loop)
1309	        libzippp_uint64 remaining = maxSize;
1310	        while (remaining>0) {
1311	            libzippp_uint64 toRead = remaining<bufferSize ? remaining : bufferSize;
1312	            libzippp_int64 result = zip_fread(zipFile, data, toRead);
1313	            if (result<0) {
1314	                iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
1315	                break;
1316	            }
1317	            if (static_cast<libzippp_uint64>(result)!=toRead) {
1318	                iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
1319	                break;
1320	            }
1321	            if (!writeFunc(data, toRead)) {
1322	                iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
1323	                break;
1324	            }
1325	            remaining -= toRead;
1326	        }
1327	        delete[] data;
1328	    } else {
1329	        iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
1330	    }
1331	    zip_fclose(zipFile);
1332	    return iRes;
1333	}
