// Verification of the compression-configuration fixes (task005)
#include <cassert>
#include <cstring>
#include <iostream>
#include "../src/libzippp.h"

using namespace libzippp;
using namespace std;

static void makeBaseArchive() {
    ZipArchive z("test.zip");
    z.open(ZipArchive::New);
    z.addData("deflated.txt", "this is some deflated data, deflated data, deflated data", 57);
    ZipEntry e = z.getEntry("deflated.txt");
    e.setCompressionMethod(DEFLATE);
    z.addData("stored.txt", "stored content", 14);
    ZipEntry e2 = z.getEntry("stored.txt");
    e2.setCompressionMethod(STORE);
    assert(z.close() == LIBZIPPP_OK);
}

// 1. archive default method must not mask existing entries; applies to new writes only
static void testArchiveDefaultDoesNotMask() {
    cout << "testArchiveDefaultDoesNotMask...";
    makeBaseArchive();

    ZipArchive z("test.zip");
    z.open(ZipArchive::Write);
    z.setCompressionMethod(STORE);

    // existing entries keep their own method, in every query flavor
    ZipEntry byName = z.getEntry("deflated.txt");
    assert(byName.getCompressionMethod() == DEFLATE);
    ZipEntry byIndex = z.getEntry((libzippp_int64)byName.getIndex());
    assert(byIndex.getCompressionMethod() == DEFLATE);
    bool seen = false;
    vector<ZipEntry> all = z.getEntries();
    for (auto& e : all) {
        if (e.getName() == "deflated.txt") { seen = true; assert(e.getCompressionMethod() == DEFLATE); }
        if (e.getName() == "stored.txt") { assert(e.getCompressionMethod() == STORE); }
    }
    assert(seen);
    // Original state shows the method at open
    assert(z.getEntry("deflated.txt", false, true, ZipArchive::Original).getCompressionMethod() == DEFLATE);
    // levels: unknown from the zip => 0, Original must not borrow later settings
    assert(byName.getCompressionLevel() == 0);
    assert(z.getEntry("deflated.txt", false, true, ZipArchive::Original).getCompressionLevel() == 0);

    // newly added file follows the archive default
    assert(z.addData("newfile.txt", "NEWCONTENT", 10));
    assert(z.getEntry("newfile.txt").getCompressionMethod() == STORE);
    // existing entries still untouched by the default
    assert(z.getEntry("deflated.txt").getCompressionMethod() == DEFLATE);
    assert(z.close() == LIBZIPPP_OK);

    // reopen: method recognized, content complete
    ZipArchive z2("test.zip");
    z2.open(ZipArchive::ReadOnly);
    ZipEntry nf = z2.getEntry("newfile.txt");
    assert(nf.getCompressionMethod() == STORE);
    assert(nf.readAsText() == "NEWCONTENT");
    assert(z2.getEntry("deflated.txt").getCompressionMethod() == DEFLATE);
    assert(z2.getEntry("deflated.txt").readAsText() == "this is some deflated data, deflated data, deflated data");
    z2.close();
    z2.unlink();
    cout << " done." << endl;
}

// 2. alternating copies: each setter preserves the other effective setting
static void testAlternatingCopies() {
    cout << "testAlternatingCopies...";
    makeBaseArchive();

    ZipArchive z("test.zip");
    z.open(ZipArchive::Write);

    ZipEntry copyA = z.getEntry("deflated.txt");
    ZipEntry copyB = copyA; // a second copy of the same entry

    assert(copyA.setCompressionLevel(5));
    assert(copyA.getCompressionLevel() == 5);
    assert(copyA.getCompressionMethod() == DEFLATE);

    // copyB holds stale attributes (level 0): changing the method must keep level 5
    assert(copyB.getCompressionLevel() == 0); // obtained objects keep their attributes
    assert(copyB.setCompressionMethod(STORE));
    assert(copyB.getCompressionMethod() == STORE);
    assert(copyB.getCompressionLevel() == 5); // effective level preserved

    // fresh query reflects the latest settings
    ZipEntry fresh = z.getEntry("deflated.txt");
    assert(fresh.getCompressionMethod() == STORE);
    assert(fresh.getCompressionLevel() == 5);

    // copyA holds a stale method (DEFLATE): changing the level must keep STORE
    assert(copyA.setCompressionLevel(9));
    assert(copyA.getCompressionLevel() == 9);
    assert(copyA.getCompressionMethod() == STORE);
    assert(z.getEntry("deflated.txt").getCompressionMethod() == STORE);
    assert(z.getEntry("deflated.txt").getCompressionLevel() == 9);

    // direct both-settings entry point on the archive
    ZipEntry copyC = z.getEntry("deflated.txt");
    assert(z.setEntryCompressionConfig(copyC, DEFLATE, 3));
    assert(copyC.getCompressionMethod() == DEFLATE);
    assert(copyC.getCompressionLevel() == 3);
    assert(z.getEntry("deflated.txt").getCompressionMethod() == DEFLATE);
    assert(z.getEntry("deflated.txt").getCompressionLevel() == 3);

    // Original state is not polluted by the pending settings
    assert(z.getEntry("deflated.txt", false, true, ZipArchive::Original).getCompressionMethod() == DEFLATE);
    assert(z.getEntry("deflated.txt", false, true, ZipArchive::Original).getCompressionLevel() == 0);

    // rename: re-obtained entry keeps the settings
    assert(z.renameEntry("deflated.txt", "renamed.txt") == 1);
    ZipEntry rn = z.getEntry("renamed.txt");
    assert(rn.getCompressionMethod() == DEFLATE);
    assert(rn.getCompressionLevel() == 3);

    assert(z.close() == LIBZIPPP_OK);

    // after commit the method persisted; the level cannot be read back (0)
    ZipArchive z2("test.zip");
    z2.open(ZipArchive::ReadOnly);
    ZipEntry r = z2.getEntry("renamed.txt");
    assert(r.getCompressionMethod() == DEFLATE);
    assert(r.getCompressionLevel() == 0);
    z2.close();
    z2.unlink();
    cout << " done." << endl;
}

// 3. invalid levels are rejected without changing anything
static void testInvalidLevelRejected() {
    cout << "testInvalidLevelRejected...";
    makeBaseArchive();

    ZipArchive z("test.zip");
    z.open(ZipArchive::Write);

    ZipEntry e = z.getEntry("deflated.txt");
    assert(e.setCompressionLevel(4));
    // DEFLATE level 10: rejected, object and archive settings unchanged
    assert(!e.setCompressionLevel(10));
    assert(e.getCompressionLevel() == 4);
    assert(e.getCompressionMethod() == DEFLATE);
    assert(z.getEntry("deflated.txt").getCompressionLevel() == 4);
    assert(z.getEntry("deflated.txt").getCompressionMethod() == DEFLATE);

    // same through the archive entry point
    assert(!z.setEntryCompressionConfig(e, DEFLATE, 10));
    assert(e.getCompressionLevel() == 4);
    assert(z.getEntry("deflated.txt").getCompressionLevel() == 4);

    // boundaries: 1 and 9 are fine
    assert(e.setCompressionLevel(1));
    assert(e.setCompressionLevel(9));
    assert(e.setCompressionLevel(0)); // back to libzip default
    assert(e.getCompressionLevel() == 0);

    assert(z.close() == LIBZIPPP_OK);
    z.unlink();
    cout << " done." << endl;
}

// 4. archive defaults that cannot be applied: add fails cleanly, pending changes kept
static void testInvalidArchiveDefault() {
    cout << "testInvalidArchiveDefault...";
    makeBaseArchive();

    ZipArchive z("test.zip");
    z.open(ZipArchive::Write);
    assert(z.addData("keep/me.txt", "KEEP", 4)); // pending addition
    ZipEntry k = z.getEntry("keep/me.txt");
    assert(k.setCompressionLevel(7));            // pending compression setting

    z.setCompressionMethod(DEFLATE);
    z.setCompressionLevel(10); // invalid for DEFLATE
    assert(!z.addData("brand/newdir/file.txt", "X", 1));
    // no new entry, no auto-created parent directories
    assert(!z.hasEntry("brand/newdir/file.txt"));
    assert(!z.hasEntry("brand/"));
    assert(!z.hasEntry("brand/newdir/"));
    // pending content and compression settings are preserved
    assert(z.hasEntry("keep/me.txt"));
    assert(z.getEntry("keep/me.txt").readAsText() == "KEEP");
    assert(z.getEntry("keep/me.txt").getCompressionLevel() == 7);
    assert(z.getEntry("deflated.txt").getCompressionMethod() == DEFLATE);

    // fixing the settings makes the very same call succeed
    z.setCompressionLevel(9);
    assert(z.addData("brand/newdir/file.txt", "X", 1));
    assert(z.getEntry("brand/newdir/file.txt").getCompressionMethod() == DEFLATE);
    assert(z.getEntry("brand/newdir/file.txt").getCompressionLevel() == 9);
    assert(z.close() == LIBZIPPP_OK);

    ZipArchive z2("test.zip");
    z2.open(ZipArchive::ReadOnly);
    assert(z2.getEntry("keep/me.txt").readAsText() == "KEEP");
    assert(z2.getEntry("brand/newdir/file.txt").readAsText() == "X");
    assert(z2.getEntry("brand/newdir/file.txt").getCompressionMethod() == DEFLATE);
    z2.close();
    z2.unlink();
    cout << " done." << endl;
}

// 5. archive default level (without a method) is used for the actual write
static void testArchiveDefaultLevelOnly() {
    cout << "testArchiveDefaultLevelOnly...";
    ZipArchive z("test.zip");
    z.open(ZipArchive::New);
    z.setCompressionLevel(8);
    string big(4096, 'a');
    assert(z.addData("lvl.txt", big.data(), big.size()));
    // the pending write reports the level chosen on the archive
    ZipEntry e = z.getEntry("lvl.txt");
    assert(e.getCompressionLevel() == 8);
    assert(z.close() == LIBZIPPP_OK);

    ZipArchive z2("test.zip");
    z2.open(ZipArchive::ReadOnly);
    ZipEntry r = z2.getEntry("lvl.txt");
    assert(r.getCompressionMethod() == DEFLATE); // libzip default
    assert(r.getCompressionLevel() == 0);        // not readable back
    assert(r.readAsText() == big);
    z2.close();
    z2.unlink();
    cout << " done." << endl;
}

// 6. reopening does not carry over the levels recorded during a previous opening
static void testNoCarryOverAcrossOpenings() {
    cout << "testNoCarryOverAcrossOpenings...";
    makeBaseArchive();

    ZipArchive z("test.zip");
    z.open(ZipArchive::Write);
    ZipEntry e = z.getEntry("deflated.txt");
    assert(e.setCompressionLevel(6));
    assert(z.getEntry("deflated.txt").getCompressionLevel() == 6);
    assert(z.close() == LIBZIPPP_OK);

    z.open(ZipArchive::Write);
    // the level recorded during the previous opening is gone
    assert(z.getEntry("deflated.txt").getCompressionLevel() == 0);
    assert(z.getEntry("deflated.txt").getCompressionMethod() == DEFLATE);
    // old-session object refuses modifications
    assert(!e.setCompressionLevel(2));
    assert(!e.setCompressionMethod(STORE));
    assert(z.close() == LIBZIPPP_OK);
    z.unlink();
    cout << " done." << endl;
}

// 7. read-only archives reject entry compression changes
static void testReadOnlyRejected() {
    cout << "testReadOnlyRejected...";
    makeBaseArchive();
    ZipArchive z("test.zip");
    z.open(ZipArchive::ReadOnly);
    ZipEntry e = z.getEntry("deflated.txt");
    assert(!e.setCompressionMethod(STORE));
    assert(!e.setCompressionLevel(3));
    assert(!z.setEntryCompressionConfig(e, STORE, 0));
    assert(e.getCompressionMethod() == DEFLATE);
    z.close();
    // closed archive rejects as well
    assert(!e.setCompressionMethod(STORE));
    assert(!e.setCompressionLevel(3));
    z.unlink();
